messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark">
<title>Gait Study · Low-Poly Treadmill</title>
<style>
  :root{ --bg:#16181b; --ink:#8a919a; --dim:#596068; --amber:#ffb454; --hot:#ff7038; --line:#2b3036; }
  html,body{margin:0;height:100%;background:var(--bg);overflow:hidden}
  #stage{position:fixed;inset:0}
  #stage canvas{display:block}
  .hud{
    position:fixed;top:26px;left:30px;z-index:2;pointer-events:none;user-select:none;
    font-family:ui-monospace,"SF Mono","Cascadia Mono",Menlo,Consolas,"Liberation Mono",monospace;
    color:var(--ink);
  }
  .hud .k{font-size:10px;letter-spacing:.24em;color:var(--dim)}
  .hud .row{display:flex;align-items:baseline;gap:14px;margin:9px 0 10px}
  #mode{font-size:15px;font-weight:700;letter-spacing:.22em;color:var(--dim);transition:color .35s}
  #spd{font-size:11px;letter-spacing:.1em;color:var(--ink)}
  .bar{width:148px;height:2px;background:var(--line);margin-bottom:10px}
  .bar i{display:block;height:100%;width:100%;background:var(--amber);transform-origin:0 50%;transform:scaleX(0)}
  .hud .foot{font-size:10px;letter-spacing:.18em;color:var(--dim)}
  .err{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;color:var(--ink);
       font:13px ui-monospace,Menlo,Consolas,monospace;letter-spacing:.08em}
</style>
</head>
<body>
<div id="stage"></div>
<div class="hud" aria-hidden="true">
  <div class="k">GAIT CYCLE · 10 S LOOP · SIDE VIEW</div>
  <div class="row"><span id="mode">IDLE</span><span id="spd">0.0 m/s</span></div>
  <div class="bar"><i id="fill"></i></div>
  <div class="foot">PROCEDURAL FIGURE · IDLE → WALK → RUN → IDLE</div>
</div>

<script type="module">
import * as THREE from './three.module.js';

/* ---------------- renderer / scene / camera ---------------- */
const stage = document.getElementById('stage');
let renderer;
try { renderer = new THREE.WebGLRenderer({ antialias:true }); }
catch(e){
  const d = document.createElement('div'); d.className = 'err';
  d.textContent = 'WEBGL UNAVAILABLE — CANNOT RUN THE SCENE';
  document.body.appendChild(d); throw e;
}
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.outputColorSpace = THREE.SRGBColorSpace;
stage.appendChild(renderer.domElement);

const TAU = Math.PI * 2;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x16181b);
scene.fog = new THREE.Fog(0x16181b, 9, 22);

const camera = new THREE.PerspectiveCamera(37, 1, 0.1, 80);
function frameCamera(){
  const aspect = innerWidth / Math.max(1, innerHeight);
  camera.aspect = aspect;
  const dist = 5.6 * Math.max(1, 1.25 / aspect);      // pull back on narrow screens
  camera.position.set(dist, 2.1 * (0.72 + 0.28 * dist / 5.6), 0);
  camera.updateProjectionMatrix();
  camera.lookAt(0, 1.02, 0.16);                        // locked side-on view
}
frameCamera();

/* ---------------- lights ---------------- */
scene.add(new THREE.HemisphereLight(0xd9dee4, 0x14161a, 1.0));
scene.add(new THREE.AmbientLight(0xffffff, 0.1));
const key = new THREE.DirectionalLight(0xffdfbe, 3.0);
key.position.set(3.6, 5.6, 2.2);
key.castShadow = true;
key.shadow.mapSize.set(2048, 2048);
const sc = key.shadow.camera;
sc.left = -3.4; sc.right = 3.4; sc.top = 3.6; sc.bottom = -2.4; sc.near = 1; sc.far = 16;
key.shadow.bias = -0.0004; key.shadow.normalBias = 0.02;
scene.add(key);
const rim = new THREE.DirectionalLight(0xa9c1d8, 1.15);
rim.position.set(-4.5, 3.2, -3.6);
scene.add(rim);

/* ---------------- floor + distant slabs ---------------- */
const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(60, 60),
  new THREE.MeshStandardMaterial({ color:0x1d2125, roughness:1 })
);
floor.rotation.x = -Math.PI/2; floor.receiveShadow = true; scene.add(floor);

const slabMat = new THREE.MeshStandardMaterial({ color:0x23272d, roughness:1 });
for(const [x,z,w,h,d] of [[-7.5,-3.6,1.0,3.2,0.8],[-9.2,1.4,1.4,5.2,1.0],[-8.1,5.6,0.9,3.0,0.9],
                          [-10.4,-0.6,1.2,6.8,1.2],[-6.9,8.4,0.8,2.2,0.8]]){
  const m = new THREE.Mesh(new THREE.BoxGeometry(w,h,d), slabMat);
  m.position.set(x, h/2, z); scene.add(m);
}

/* ---------------- materials + box helper ---------------- */
const M = {
  frame : new THREE.MeshStandardMaterial({ color:0x3a4148, roughness:0.55, metalness:0.2 }),
  dark  : new THREE.MeshStandardMaterial({ color:0x2b3036, roughness:0.7,  metalness:0.1 }),
  rib   : new THREE.MeshStandardMaterial({ color:0x23282d, roughness:0.8 }),
  roller: new THREE.MeshStandardMaterial({ color:0x1e2226, roughness:0.5,  metalness:0.35, flatShading:true }),
  slat  : new THREE.MeshStandardMaterial({ color:0x262b30, roughness:0.95 }),
  shirt : new THREE.MeshStandardMaterial({ color:0xbd6f4c, roughness:0.9 }),
  pants : new THREE.MeshStandardMaterial({ color:0x4a505a, roughness:0.95 }),
  skin  : new THREE.MeshStandardMaterial({ color:0xe0d3bf, roughness:0.9 }),
  hair  : new THREE.MeshStandardMaterial({ color:0x26211d, roughness:0.9 }),
  shoe  : new THREE.MeshStandardMaterial({ color:0x24272b, roughness:0.9 }),
  sole  : new THREE.MeshStandardMaterial({ color:0xd8d0bf, roughness:0.9 }),
  vent  : new THREE.MeshStandardMaterial({ color:0x14171b, roughness:0.9 }),
};
function box(w,h,d,mat,x,y,z,parent,cast=true){
  const m = new THREE.Mesh(new THREE.BoxGeometry(w,h,d), mat);
  m.position.set(x,y,z); m.castShadow = cast; m.receiveShadow = true;
  parent.add(m); return m;
}

/* ---------------- treadmill (slat belt wraps real rollers) ---------------- */
const tm = new THREE.Group(); scene.add(tm);
const Lh = 0.85, RY = 0.14, R = 0.09, SLAT_T = 0.035, SLAT_W = 0.64, SLAT_D = 0.115;
const BELT_TOP = RY + R + SLAT_T/2;
const LOOP = 4*Lh + TAU*R, NSLAT = 30, SPACING = LOOP/NSLAT;

box(0.80,0.10,1.50, M.dark, 0,0.05,0, tm);           // motor housing
box(0.70,0.06,1.30, M.rib,  0,0.13,0, tm);           // center ridge under belt
box(0.07,0.12,2.00, M.frame,  0.365,0.06,0, tm);     // side rails
box(0.07,0.12,2.00, M.frame, -0.365,0.06,0, tm);

const rollerGeo = new THREE.CylinderGeometry(0.068,0.068,0.74,18,1); rollerGeo.rotateZ(Math.PI/2);
const rollers = [];
for(const s of [-1,1]){
  const r = new THREE.Mesh(rollerGeo, M.roller);
  r.position.set(0, RY, s*Lh); r.castShadow = true; r.receiveShadow = true;
  tm.add(r); rollers.push(r);
}

const slatGeo = new THREE.BoxGeometry(SLAT_W, SLAT_T, SLAT_D);
const slats = [];
for(let i=0;i<NSLAT;i++){
  const s = new THREE.Mesh(slatGeo, M.slat);
  s.castShadow = true; s.receiveShadow = true;
  tm.add(s); slats.push(s);
}
let beltOffset = 0;
function layoutBelt(){ /* slats parametrized by arc length around the full loop */
  for(let i=0;i<NSLAT;i++){
    let s = (i*SPACING + beltOffset) % LOOP; if(s < 0) s += LOOP;
    const m = slats[i];
    if(s < 2*Lh){ m.position.set(0, RY+R, Lh - s); m.rotation.set(0,0,0); }
    else if(s < 2*Lh + Math.PI*R){ const t=(s-2*Lh)/R;
      m.position.set(0, RY+R*Math.cos(t), -Lh - R*Math.sin(t)); m.rotation.set(-t,0,0); }
    else if(s < 4*Lh + Math.PI*R){ m.position.set(0, RY-R, -Lh + (s-2*Lh-Math.PI*R)); m.rotation.set(Math.PI,0,0); }
    else { const t=(s-4*Lh-Math.PI*R)/R;
      m.position.set(0, RY-R*Math.cos(t), Lh + R*Math.sin(t)); m.rotation.set(Math.PI-t,0,0); }
  }
}
layoutBelt();

/* console (slightly yawed toward the camera) */
const consoleG = new THREE.Group(); consoleG.position.set(0,0,0.72); consoleG.rotation.y = -0.42; tm.add(consoleG);
box(0.055,1.04,0.05, M.frame,  0.23,0.62,0.10, consoleG);
box(0.055,1.04,0.05, M.frame, -0.23,0.62,0.10, consoleG);
box(0.40,0.045,0.04, M.frame,  0,0.30,0.10, consoleG);
box(0.11,0.025,0.16, M.dark,   0.23,0.112,0.10, consoleG);
box(0.11,0.025,0.16, M.dark,  -0.23,0.112,0.10, consoleG);
const headC = new THREE.Group(); headC.position.set(0,1.17,0.02); headC.rotation.x = -0.42; consoleG.add(headC);
box(0.62,0.16,0.13, M.frame, 0,0.02,0, headC);

/* console screen (canvas texture) */
const scrCan = document.createElement('canvas'); scrCan.width = 512; scrCan.height = 96;
const scx = scrCan.getContext('2d');
const scrTex = new THREE.CanvasTexture(scrCan);
scrTex.colorSpace = THREE.SRGBColorSpace; scrTex.anisotropy = 4;
const screenMesh = new THREE.Mesh(new THREE.PlaneGeometry(0.46,0.086), new THREE.MeshBasicMaterial({ map:scrTex }));
screenMesh.position.set(0,0.045,-0.0665); screenMesh.rotation.y = Math.PI; headC.add(screenMesh);
function drawScreen(mode, spd){
  scx.fillStyle = '#0b0d10'; scx.fillRect(0,0,512,96);
  scx.fillStyle = mode==='RUN' ? '#ff7038' : mode==='WALK' ? '#ffb454' : '#5a636d';
  scx.font = '700 46px ui-monospace, Menlo, Consolas, monospace';
  scx.textAlign = 'left'; scx.textBaseline = 'middle';
  scx.fillText(mode, 26, 50);
  scx.fillStyle = '#9aa2ab'; scx.font = '500 26px ui-monospace, Menlo, Consolas, monospace';
  scx.textAlign = 'right';
  scx.fillText(spd.toFixed(1)+' m/s', 488, 52);
  scrTex.needsUpdate = true;
}

/* console LED strip */
const ledGeo = new THREE.BoxGeometry(0.03,0.022,0.014);
const ledOn  = new THREE.MeshBasicMaterial({ color:0xffb454 });
const ledOff = new THREE.MeshBasicMaterial({ color:0x272c31 });
const leds = [];
for(let i=0;i<10;i++){
  const l = new THREE.Mesh(ledGeo, ledOff);
  l.position.set(-0.225 + i*0.05, -0.042, -0.067);
  headC.add(l); leds.push(l);
}

/* side gauge (mechanical belt-speed meter, faces the camera) */
const gCan = document.createElement('canvas'); gCan.width = 256; gCan.height = 160;
const gg = gCan.getContext('2d');
const gTex = new THREE.CanvasTexture(gCan);
gTex.colorSpace = THREE.SRGBColorSpace; gTex.anisotropy = 4;
box(0.012,0.115,0.175, M.dark, 0.4015,0.05,0.18, tm);
const gaugeMesh = new THREE.Mesh(new THREE.PlaneGeometry(0.16,0.10), new THREE.MeshBasicMaterial({ map:gTex }));
gaugeMesh.position.set(0.4085,0.05,0.18); gaugeMesh.rotation.y = Math.PI/2; tm.add(gaugeMesh);
for(let i=0;i<3;i++) box(0.012,0.014,0.15, M.vent, -0.402, 0.032+i*0.021, 0.18, tm, false);

const GMAX = 2.5, A0 = Math.PI*0.75, A1 = Math.PI*2.25;
function drawGauge(spd, mode){
  const W=256,H=160,cx=128,cy=72,r=42;
  gg.fillStyle='#12151a'; gg.fillRect(0,0,W,H);
  gg.strokeStyle='#3a4149'; gg.lineWidth=5; gg.strokeRect(5.5,5.5,W-11,H-11);
  gg.lineCap='round';
  gg.beginPath(); gg.arc(cx,cy,r,A0,A1); gg.strokeStyle='#272d34'; gg.lineWidth=8; gg.stroke();
  const tv = Math.min(spd/GMAX, 1);
  if(tv > 0.004){
    gg.beginPath(); gg.arc(cx,cy,r,A0,A0+(A1-A0)*tv);
    gg.strokeStyle = spd > 1.5 ? '#ff7038' : '#ffb454'; gg.lineWidth=8; gg.stroke();
  }
  gg.textAlign='center'; gg.textBaseline='middle';
  for(let i=0;i<=10;i++){
    const a = A0+(A1-A0)*i/10, maj = i%2===0;
    gg.beginPath();
    gg.moveTo(cx+Math.cos(a)*(r-5),  cy+Math.sin(a)*(r-5));
    gg.lineTo(cx+Math.cos(a)*(maj?r-12:r-9), cy+Math.sin(a)*(maj?r-12:r-9));
    gg.strokeStyle = maj ? '#79828c' : '#454c55'; gg.lineWidth = maj?3:2; gg.stroke();
    if(maj){
      gg.fillStyle='#8a919a'; gg.font='600 12px ui-monospace, Menlo, Consolas, monospace';
      gg.fillText((i/10*GMAX).toFixed(1), cx+Math.cos(a)*(r+13), cy+Math.sin(a)*(r+13));
    }
  }
  const a = A0+(A1-A0)*tv;
  gg.beginPath();
  gg.moveTo(cx-Math.cos(a)*9, cy-Math.sin(a)*9);
  gg.lineTo(cx+Math.cos(a)*(r-11), cy+Math.sin(a)*(r-11));
  gg.strokeStyle='#ffb454'; gg.lineWidth=3; gg.stroke();
  gg.beginPath(); gg.arc(cx,cy,5.5,0,TAU); gg.fillStyle='#1b2026'; gg.fill();
  gg.lineWidth=2; gg.strokeStyle='#5a636d'; gg.stroke();
  gg.textBaseline='alphabetic';
  gg.fillStyle = mode==='RUN' ? '#ff7038' : mode==='WALK' ? '#ffb454' : '#79828c';
  gg.font='700 18px ui-monospace, Menlo, Consolas, monospace';
  gg.fillText(mode, cx, 134);
  gg.fillStyle='#8a919a'; gg.font='500 13px ui-monospace, Menlo, Consolas, monospace';
  gg.fillText(spd.toFixed(1)+' m/s', cx, 151);
  gTex.needsUpdate = true;
}

/* ---------------- low-poly humanoid ---------------- */
const fig = new THREE.Group(); fig.position.y = BELT_TOP; scene.add(fig);
const hips = new THREE.Group(); hips.position.y = 0.928; fig.add(hips);
box(0.27,0.15,0.18, M.pants, 0,0,0, hips);                       // pelvis

function buildLeg(sx){
  const hip = new THREE.Group(); hip.position.set(0.095*sx,-0.02,0); hips.add(hip);
  box(0.12,0.12,0.15, M.pants, 0, 0.01,0, hip);                  // hip cap
  box(0.115,0.42,0.13, M.pants, 0,-0.21,0, hip);                 // thigh
  const knee = new THREE.Group(); knee.position.set(0,-0.42,0); hip.add(knee);
  box(0.10,0.10,0.12, M.pants, 0, 0.005,0, knee);                // knee cap
  box(0.095,0.40,0.105, M.pants, 0,-0.20,0, knee);               // shin
  const ankle = new THREE.Group(); ankle.position.set(0,-0.40,0); knee.add(ankle);
  box(0.11,0.065,0.235, M.shoe, 0,-0.032,0.045, ankle);          // shoe
  box(0.115,0.028,0.245, M.sole, 0,-0.072,0.045, ankle);         // sole
  return { hip, knee, ankle };
}
const legL = buildLeg(-1), legR = buildLeg(1);

const spine = new THREE.Group(); spine.position.set(0,0.085,0); hips.add(spine);
box(0.29,0.18,0.20, M.shirt, 0,0.07,0, spine);                   // lower torso
box(0.35,0.27,0.22, M.shirt, 0,0.285,0, spine);                  // chest
const headP = new THREE.Group(); headP.position.set(0,0.50,0.005); spine.add(headP);
box(0.09,0.09,0.095, M.skin, 0,0.02,0.005, headP);               // neck
box(0.20,0.22,0.21, M.skin, 0,0.135,0.005, headP);               // head
box(0.225,0.10,0.23, M.hair, 0,0.262,-0.012, headP);             // hair cap
box(0.225,0.15,0.05, M.hair, 0,0.165,-0.108, headP);             // back hair

function buildArm(sx){
  const sh = new THREE.Group(); sh.position.set(0.215*sx,0.36,0); spine.add(sh);
  box(0.14,0.12,0.13, M.shirt, 0,-0.01,0, sh);                   // shoulder cap
  box(0.105,0.30,0.115, M.shirt, 0,-0.16,0, sh);                 // sleeve
  const el = new THREE.Group(); el.position.set(0,-0.31,0); sh.add(el);
  box(0.09,0.08,0.10, M.skin, 0,0.005,0, el);                    // elbow cap
  box(0.085,0.26,0.09, M.skin, 0,-0.14,0, el);                   // forearm
  box(0.088,0.11,0.075, M.skin, 0,-0.315,0.008, el);             // hand
  return { sh, el };
}
const armL = buildArm(-1), armR = buildArm(1);

/* ---------------- gait presets ---------------- */
/* knee/foot are keyframed over one stride: knots at 0, π/2(contact), π(mid-stance),
   3π/2(toe-off), 5.45(swing peak), 2π — values tuned so the stance foot plants on the belt */
const GAIT = {
  idle: { freq:0,    m:0,     A:0,
          knee:[0.06,0.06,0.06,0.06,0.06,0.06], foot:[0,0,0,0,0,0],
          armM:0, armA:0, elbB:0.16, elbP:0, bobB:0.002, bobO:0,
          lean:0, sway:0, hipTw:0, spTw:0, splay:0.075, belt:0 },
  walk: { freq:0.92, m:-0.11, A:0.27,
          knee:[0.70,0.30,0.12,0.50,0.85,0.70], foot:[-0.15,-0.12,0.02,0.30,-0.22,-0.15],
          armM:-0.04, armA:0.42, elbB:0.42, elbP:0.25, bobB:-0.022, bobO:0.012,
          lean:0.06, sway:0.022, hipTw:0.06, spTw:0.05, splay:0.09, belt:0.85 },
  run:  { freq:1.42, m:-0.10, A:0.38,
          knee:[1.10,0.48,0.36,0.75,1.50,1.10], foot:[-0.25,-0.16,0.03,0.42,-0.35,-0.25],
          armM:-0.10, armA:0.85, elbB:1.30, elbP:0.35, bobB:-0.033, bobO:0.016,
          lean:0.28, sway:0.012, hipTw:0.10, spTw:0.12, splay:0.12, belt:2.3 }
};

const KNOT = [0, Math.PI/2, Math.PI, 3*Math.PI/2, 5.45, TAU];
function smoother(u){ u = u<0?0 : u>1?1 : u; return u*u*u*(u*(6*u-15)+10); }
function sampleKeys(vals, ph){
  let x = ph % TAU; if(x < 0) x += TAU; if(x > TAU) x = TAU;
  let i = 0; while(i < 4 && x > KNOT[i+1]) i++;
  const u = (x - KNOT[i]) / (KNOT[i+1] - KNOT[i]);
  return vals[i] + (vals[i+1]-vals[i]) * smoother(u);
}
function ss(e0,e1,x){ const u = Math.min(1, Math.max(0, (x-e0)/(e1-e0))); return u*u*(3-2*u); }

const kK = new Array(6), kF = new Array(6), P = {};
function blend(w){
  const a = GAIT.idle, b = GAIT.walk, c = GAIT.run;
  for(const k in a){
    if(k === 'knee' || k === 'foot') continue;
    P[k] = a[k]*w.wI + b[k]*w.wW + c[k]*w.wR;
  }
  for(let i=0;i<6;i++){
    kK[i] = a.knee[i]*w.wI + b.knee[i]*w.wW + c.knee[i]*w.wR;
    kF[i] = a.foot[i]*w.wI + b.foot[i]*w.wW + c.foot[i]*w.wR;
  }
}
function computeWeights(t){ /* 0–2 idle · 2–5 walk · 5–8 run · 8–10 idle, 0.5 s crossfades */
  const wW = ss(2,2.5,t) * (1 - ss(5,5.5,t));
  const wR = ss(5,5.5,t) * (1 - ss(8,8.5,t));
  return { wI: 1 - wW - wR, wW, wR };
}

/* ---------------- main loop ---------------- */
const clock = new THREE.Clock();
let simT = 0, gaitPhase = 0, gaugeAcc = 1;
const hud = { mode: document.getElementById('mode'), spd: document.getElementById('spd'), fill: document.getElementById('fill') };
let hudMode = '', hudSpd = '';
const colIdle = '#596068', colWalk = '#ffb454', colRun = '#ff7038';
const cAmber = new THREE.Color(0xffb454), cHot = new THREE.Color(0xff7038), cLed = new THREE.Color();

function tick(){
  requestAnimationFrame(tick);
  const dt = Math.min(clock.getDelta(), 0.05);
  simT += dt;
  const t = simT % 10;
  const w = computeWeights(t);
  blend(w);

  gaitPhase += P.freq * TAU * dt;
  if(gaitPhase > TAU*1000) gaitPhase %= TAU;
  const p = gaitPhase, sn = Math.sin(p);
  const breathe = Math.sin(simT * 1.5);

  /* legs — stride phase, opposite legs offset by π */
  const p2 = p + Math.PI;
  legL.hip.rotation.x   = P.m - P.A * Math.sin(p);
  legL.knee.rotation.x  = sampleKeys(kK, p);
  legL.ankle.rotation.x = sampleKeys(kF, p);
  legR.hip.rotation.x   = P.m - P.A * Math.sin(p2);
  legR.knee.rotation.x  = sampleKeys(kK, p2);
  legR.ankle.rotation.x = sampleKeys(kF, p2);

  /* arms — counter-phase to legs, elbows pump */
  armL.sh.rotation.x = P.armM + P.armA*sn + 0.012*breathe*w.wI;
  armR.sh.rotation.x = P.armM - P.armA*sn + 0.012*breathe*w.wI;
  armL.sh.rotation.z = -P.splay;
  armR.sh.rotation.z =  P.splay;
  armL.el.rotation.x = -(P.elbB + P.elbP*Math.max(0,-sn));
  armR.el.rotation.x = -(P.elbB + P.elbP*Math.max(0, sn));

  /* torso lean + counter-rotation, head stabilization */
  spine.rotation.x = P.lean + 0.015*breathe*w.wI;
  spine.rotation.y =  P.spTw*sn;
  hips.rotation.y  = -P.hipTw*sn;
  headP.rotation.x = -P.lean*0.55;
  headP.rotation.y = -P.spTw*0.6*sn;

  /* vertical bounce + lateral weight shift */
  fig.position.y = BELT_TOP + P.bobB + P.bobO*Math.cos(2*p) + 0.006*breathe*w.wI;
  fig.position.x = P.sway*Math.cos(p) + 0.006*Math.sin(simT*0.55)*w.wI;

  /* belt + rollers */
  const beltV = P.belt;
  if(beltV > 1e-4){
    beltOffset += beltV*dt; if(beltOffset >= SPACING) beltOffset %= SPACING;
    layoutBelt();
  }
  for(const r of rollers) r.rotation.x -= beltV/0.068*dt;

  /* console LEDs */
  const norm = Math.min(1, beltV/2.3);
  const lit = 1 + Math.round(9*norm);
  cLed.copy(cAmber).lerp(cHot, norm).multiplyScalar(0.55 + 0.45*norm);
  ledOn.color.copy(cLed);
  for(let i=0;i<10;i++) leds[i].material = i < lit ? ledOn : ledOff;

  /* HUD + diegetic readouts */
  const mode = w.wR > 0.5 ? 'RUN' : w.wW > 0.5 ? 'WALK' : 'IDLE';
  if(mode !== hudMode){
    hudMode = mode; hud.mode.textContent = mode;
    hud.mode.style.color = mode==='RUN' ? colRun : mode==='WALK' ? colWalk : colIdle;
    drawScreen(mode, beltV); drawGauge(beltV, mode);
  }
  const spdTxt = beltV.toFixed(1);
  if(spdTxt !== hudSpd){ hudSpd = spdTxt; hud.spd.textContent = spdTxt + ' m/s'; }
  hud.fill.style.transform = 'scaleX(' + (t/10).toFixed(4) + ')';

  gaugeAcc += dt;
  if(gaugeAcc > 0.05){ gaugeAcc = 0; drawGauge(beltV, mode); drawScreen(mode, beltV); }

  renderer.render(scene, camera);
}
drawScreen('IDLE', 0);
drawGauge(0, 'IDLE');
tick();

addEventListener('resize', () => {
  renderer.setSize(innerWidth, innerHeight);
  frameCamera();
});
